#ifndef FECHA_H
#define FECHA_H

typedef enum {
  FALSO,
  VERDADERO
} TBool;

typedef struct {
  int dia;
  int mes;
  int anio;
} TFecha;

TFecha crear(int dia, int mes, int anio);
TBool esBisiesto(TFecha f);
int diasDelMes(TFecha f);
TFecha sumarDias(TFecha f, int n);
void mostrar(TFecha f);

#endif

#include <stdio.h>
#include "fecha.h"

TFecha crear(int dia, int mes, int anio) {
  TFecha f;

  f.dia = dia;
  f.mes = mes;
  f.anio = anio;
  return f;
}

TBool esBisiesto(TFecha f) {
  if ((f.anio % 4 == 0 && f.anio % 100 != 0) || f.anio % 400 == 0) {
    return VERDADERO;
  }
  return FALSO;
}

int diasDelMes(TFecha f) {
  int dias;

  if (f.mes == 2) {
    if (esBisiesto(f) == VERDADERO) {
      dias = 29;
    } else {
      dias = 28;
    }
  } else if (f.mes == 4 || f.mes == 6 || f.mes == 9 || f.mes == 11) {
    dias = 30;
  } else {
    dias = 31;
  }
  return dias;
}

TFecha sumarDias(TFecha f, int n) {
  for (int i = 0; i < n; i++) {
    f.dia = f.dia + 1;
    if (f.dia > diasDelMes(f)) {
      f.dia = 1;
      f.mes = f.mes + 1;
      if (f.mes > 12) {
        f.mes = 1;
        f.anio = f.anio + 1;
      }
    }
  }
  return f;
}

void mostrar(TFecha f) {
  printf("%d/%d/%d", f.dia, f.mes, f.anio);
}

#include <stdio.h>
#include "fecha.h"

int main() {
  int dia, mes, anio, n;
  TFecha f;

  scanf("%d", &dia);
  scanf("%d", &mes);
  scanf("%d", &anio);
  scanf("%d", &n);
  f = crear(dia, mes, anio);
  f = sumarDias(f, n);
  mostrar(f);
  if (esBisiesto(f) == VERDADERO) {
    printf("\nbisiesto");
  } else {
    printf("\nno bisiesto");
  }
  return 0;
}

