void mostrar(TFecha f) {
  printf("%d/%d/%d", f.dia, f.mes, f.anio);
}

TFecha sumarMeses(TFecha f, int n) {
  f.mes = f.mes + n;
  while (f.mes > 12) {
    f.mes = f.mes - 12;
    f.anio = f.anio + 1;
  }
  if (f.dia > diasDelMes(f)) {
    f.dia = diasDelMes(f);
  }
  return f;
}

TFecha sumarAnios(TFecha f, int n) {
  f.anio = f.anio + n;
  if (f.dia > diasDelMes(f)) {
    f.dia = diasDelMes(f);
  }
  return f;
}

#include <stdio.h>
#include "fecha.h"

int main() {
  int dia, mes, anio, meses, anios;
  TFecha f;

  scanf("%d", &dia);
  scanf("%d", &mes);
  scanf("%d", &anio);
  scanf("%d", &meses);
